import { useCallback } from 'react';
import { JxChip, JxTagInput, useControllableState } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  label?: string;
  placeholder?: string;
  emptyText?: string;
  onChange?: (value: string[]) => void;
}

function ArticleTagPicker({
  value,
  defaultValue = [],
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  emptyText = 'Пока не выбрано ни одного тега',
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useControllableState<string[]>(value, defaultValue, onChange);

  const removeTag = useCallback(
    (tag: string) => {
      setTags(tags.filter((item) => item !== tag));
    },
    [setTags, tags],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={setTags}
      />
      {tags.length > 0 ? (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      ) : (
        <span style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-sans)' }}>
          {emptyText}
        </span>
      )}
    </div>
  );
}

export default ArticleTagPicker;

